import{_ as l,l as i,o as e,c as n,v as r,p as c,x as t,d as p,i as s,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"预防性储蓄与缓冲存量","description":"","frontmatter":{"title":"预防性储蓄与缓冲存量","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/precautionary-buffer-stock.md","filePath":"econ/precautionary-buffer-stock.md","lastUpdated":1789023840000}'),d={name:"econ/precautionary-buffer-stock.md"};function u(m,a,h,f,_,A){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="预防性储蓄与缓冲存量" tabindex="-1">预防性储蓄与缓冲存量 <a class="header-anchor" href="#预防性储蓄与缓冲存量" aria-label="Permalink to &quot;预防性储蓄与缓冲存量&quot;">​</a></h1><div class="epigraph"><p>若边际效用凸，收入风险本身就会提高储蓄：不是为了退休，是为了给坏年景留一笔缓冲。</p><footer>—— Leland, Saving and Uncertainty: The Precautionary Demand for Saving, QJE 1968；Carroll, Buffer-Stock Saving and the Life Cycle/Permanent Income Hypothesis, QJE 1997</footer></div><p><a href="/econ/permanent-income">上一课</a>的确定性等价把风险关掉。本课缺口是：当 \\(u&#39;&#39;&#39;\\gt 0\\)（谨慎）且劳动收入不可完全保险，欧拉里多出一项预防性溢价，目标资产变成缓冲存量。不重写 Friedman 的永久/暂时切法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二次效用使期望边际效用等于边际效用的期望，收入方差不进消费。Leland（1968）指出：凸的 \\(u&#39;\\) 让风险提高 \\(\\mathbb{E}u&#39;(c_{t+1})\\)，为恢复欧拉必须压低当期 \\(c\\)，即预防性储蓄。Kimball（1990）把谨慎系数 \\(-u&#39;&#39;&#39;/u&#39;&#39;\\) 从风险厌恶里拆出来。Carroll（1992, 1997）与 Deaton（1991）在借贷下限附近做成缓冲存量：人有一个目标财富–永久收入比，低于则储蓄，高于则消耗，消费对收入短期敏感，但不是 Keynes 的固定 \\(c\\)。</p><p>缺口是给 PIH 加上不可保风险，而不是重推 <a href="/econ/expected-utility">vNM</a>。伯努利 \\(u\\) 已有，只动三阶。</p><p><span class="marginnote">缓冲存量需要不耐烦（\\(\\beta(1+r)\\lt 1\\)）或借贷约束，否则财富会漂到无限来自保。Carroll 把不耐烦与失业风险焊在一起，得到稳定的目标比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>劳动收入含持久与暂时冲击，债券利率外生，可能有 \\(a_{t+1}\\ge 0\\)。欧拉在约束不绑定时成立，绑定时变不等式。政策函数 \\(c(x)\\) 对现金 \\(x\\) 凹：穷时几乎吃掉收入，富时接近 PIH。目标缓冲使财富分布集中在约束附近，加总后仍有正的短期 MPC。</p>',9)),(e(),c(E,null,{default:t(()=>[s(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIH%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%AD%89%E4%BB%B7%20PIH%22%5D%20--%3E%20PRU%5B%22u'''%3E0%20%E4%B8%8E%E4%B8%8D%E5%8F%AF%E4%BF%9D%E6%94%B6%E5%85%A5%22%5D%0A%20%20PRU%20--%3E%20PREC%5B%22%E9%A2%84%E9%98%B2%E6%80%A7%3A%20%E5%8E%8B%E4%BD%8E%E5%BD%93%E6%9C%9F%20c%22%5D%0A%20%20PREC%20--%3E%20BUF%5B%22%E7%9B%AE%E6%A0%87%E8%B4%A2%E5%AF%8C-%E6%94%B6%E5%85%A5%E6%AF%94%22%5D%0A%20%20BUF%20--%3E%20MPC%5B%22%E7%BA%A6%E6%9D%9F%E9%99%84%E8%BF%91%E9%AB%98%20MPC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>本课不估计谨慎系数。也不把股票当缓冲：参与之谜后课再写；这里的资产是无风险或广义流动性财富。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是边际效用在低收入状态特别高。无法用 Arrow–Debreu 证券把劳动收入在状态间挪走时，唯一的自保是先存一笔。冲击到来，缓冲下降，MPC 上升，消费看起来「过度敏感」——下一课把这句话变成对流动性约束的检验。增长与退休仍按 LCH 提供慢变量；缓冲是快变量，对年收入波动作出反应。</p><p>与<a href="/econ/equity-premium-puzzle">股权溢价</a>的接口：总量消费仍然平滑，因为缓冲在家庭之间对冲特异风险；谜用的是加总 \\(c\\)，不是否定微观预防性储蓄。</p><p>Kimball 的谨慎与 Arrow–Pratt 的厌恶不是同一阶：厌恶由 \\(u&#39;&#39;\\) 管对已知风险的价格，谨慎由 \\(u&#39;&#39;&#39;\\) 管「要不要先存一笔」。二次效用厌恶仍在，预防性为零——这正是 PIH 确定性等价能写出来的原因。Carroll 的目标比把不耐烦与失业风险焊死，避免财富漂到无限；没有这条，预防性储蓄只有水平，没有缓冲存量的均值回复。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全市场或可对冲的收入风险把预防性项关掉。习惯形成改的是 \\(u\\) 的状态变量，与谨慎不同。现时偏差也会提高流动资产需求，但动机是自我控制而非 \\(u&#39;&#39;&#39;\\)。本课不把三者混成一个「储蓄高」的故事。</p><p>后课默认：说到缓冲存量，指谨慎加约束下的目标财富；说到过度敏感，先问是不是约束绑住了欧拉。</p><p>目标财富–收入比把预防性储蓄从「永远更高」变成对冲击的均值回复。</p><p>特异风险在加总后可对冲，故微观缓冲与总量消费平滑可以同时成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>谨慎使收入风险进入储蓄，确定性等价失败。</li><li>缓冲存量：目标财富–收入比，约束附近 MPC 高。</li><li>不重写 PIH 的永久成分，只加上不可保风险。</li><li>谨慎是三阶，厌恶是二阶，二次效用关掉本课。</li><li>约束附近的高 MPC 接到下一课过度敏感。</li><li>出处：Leland, <em>QJE</em> 1968；Kimball, <em>Econometrica</em> 1990；Deaton, <em>Econometrica</em> 1991；Carroll, <em>QJE</em> 1997。</li></ul>',12))])}const b=l(d,[["render",u]]);export{B as __pageData,b as default};
